SELECT COUNT(*) AS rent_listings_count
FROM nlq.listings
WHERE rent_price_per_week IS NOT NULL;

SELECT COUNT(*) AS yoga_mat_count
FROM nlq.listings
WHERE title ILIKE '%yoga mat%' OR description ILIKE '%yoga mat%';

select max(agreed_price) as max_sold_price
from nlq.my_deals
where my_role = 'seller' and status = 'completed';

SELECT COUNT(*) AS late_returns
FROM nlq.my_deals
WHERE my_role = 'seller' AND returned_late = true;

SELECT COUNT(*) AS conversations_without_seller_reply
FROM nlq.conversations
WHERE first_seller_reply_at IS NULL;

select count(*) as student_count
from (
   select d.seller_id
   from nlq.deals d
   join nlq.calendar c on c.day = d.completed_on
   where d.deal_type='sale' and d.status='completed'
     and c.day >= '2025-07-01' and c.day <= '2026-06-30'
   group by d.seller_id
   having count(*) >= 5
) sub;

SELECT COUNT(*) AS listings_removed_by_seller
FROM nlq.listings_all
WHERE status = 'removed';

SELECT ROUND(AVG(((resolved_at AT TIME ZONE 'America/New_York')::date - filed_on)::numeric), 2) AS avg_resolution_days
FROM nlq.reports
WHERE status = 'resolved' AND resolved_at IS NOT NULL;

SELECT COUNT(*) AS listings_without_photos
FROM nlq.listings_all
WHERE photo_count IS NULL OR photo_count = 0;

select count(*) as pending_requests
from nlq.deals
where status = 'requested';
